sys_ui_page.client_script:
// Script Include
var PDFGenerator = Class.create();
PDFGenerator.prototype = Object.extendsObject(AbstractAjaxProcessor, {
  createPDF: function() {
    var pdf = new GlidePDFDocument();
    pdf.addText(0, 0, "Hello World");
    var bytes = pdf.getBytes(); // binary content
    return GlideStringUtil.base64Encode(bytes);
  }
});
